// ── Product interface (via shared base class) ────────────────────
class Notification {
  send(message) { throw new Error('send() must be implemented'); }
  get channelName() { throw new Error('channelName must be implemented'); }
}

// ── Concrete Products ────────────────────────────────────────────
class EmailNotification extends Notification {
  constructor(address) { super(); this._address = address; }
  get channelName() { return 'Email'; }
  send(message) {
    console.log(`[Email → ${this._address}] ${message}`);
    return { channel: 'email', to: this._address, message };
  }
}

class SlackNotification extends Notification {
  constructor(webhook) { super(); this._webhook = webhook; }
  get channelName() { return 'Slack'; }
  send(message) {
    console.log(`[Slack → ${this._webhook}] ${message}`);
    return { channel: 'slack', webhook: this._webhook, message };
  }
}

class SMSNotification extends Notification {
  constructor(phone) { super(); this._phone = phone; }
  get channelName() { return 'SMS'; }
  send(message) {
    console.log(`[SMS → ${this._phone}] ${message}`);
    return { channel: 'sms', to: this._phone, message };
  }
}

// ── Creator (abstract base) ──────────────────────────────────────
class NotificationService {
  // Factory method — subclasses override this
  createNotification() { throw new Error('createNotification() must be implemented'); }

  // Template method — implemented using the factory method
  notify(message) {
    const notif = this.createNotification();
    console.log(`Dispatching via ${notif.channelName}...`);
    return notif.send(message);
  }

  broadcast(messages) {
    return messages.map(msg => this.notify(msg));
  }
}

// ── Concrete Creators ────────────────────────────────────────────
class EmailService extends NotificationService {
  constructor(address) { super(); this._address = address; }
  createNotification() { return new EmailNotification(this._address); }
}

class SlackService extends NotificationService {
  constructor(webhook) { super(); this._webhook = webhook; }
  createNotification() { return new SlackNotification(this._webhook); }
}

class SMSService extends NotificationService {
  constructor(phone) { super(); this._phone = phone; }
  createNotification() { return new SMSNotification(this._phone); }
}

// ── Client code — depends only on NotificationService interface ──
function alertOpsTeam(service, alerts) {
  return service.broadcast(alerts);
}

const emailSvc = new EmailService('ops@company.com');
const slackSvc = new SlackService('hooks.slack.com/xyz');

alertOpsTeam(emailSvc, ['Server down', 'DB latency high']);
alertOpsTeam(slackSvc, ['Server restored']);

// ── Simple factory comparison ─────────────────────────────────────
// (NOT a Factory Method — requires editing when adding new types)
function createNotificationSimple(type, target) {
  switch (type) {
    case 'email': return new EmailNotification(target);
    case 'slack': return new SlackNotification(target);
    case 'sms':   return new SMSNotification(target);
    default: throw new Error(`Unknown type: ${type}`);
  }
}
console.log(createNotificationSimple('sms', '+1-555-0100').send('Test'));
// Adding 'push' requires editing this switch — OCP violated.

// ── Factory Method: structural skeleton ─────────────────────────

// Product interface
class Product {
  operate() { throw new Error('operate() not implemented'); }
}

// Concrete Products
class ConcreteProductA extends Product {
  operate() { return 'Result from Product A'; }
}
class ConcreteProductB extends Product {
  operate() { return 'Result from Product B'; }
}

// Creator — declares the factory method
class Creator {
  // Override in subclasses
  createProduct() { throw new Error('createProduct() not implemented'); }

  // Uses the factory method internally
  someOperation() {
    const product = this.createProduct(); // polymorphic call
    return `Creator + [${product.operate()}]`;
  }
}

// Concrete Creators — each owns one product type
class CreatorA extends Creator {
  createProduct() { return new ConcreteProductA(); }
}
class CreatorB extends Creator {
  createProduct() { return new ConcreteProductB(); }
}

// ── JS alternative: registry pattern (no subclassing) ───────────
const productRegistry = {
  A: () => new ConcreteProductA(),
  B: () => new ConcreteProductB(),
};
function createProduct(type) {
  const factory = productRegistry[type];
  if (!factory) throw new Error(`Unknown product type: ${type}`);
  return factory();
}
// Add new product: productRegistry.C = () => new ConcreteProductC();
// Zero edits to existing code — OCP satisfied via registry.

const c = new CreatorA();
console.log(c.someOperation()); // Creator + [Result from Product A]
const d = new CreatorB();
console.log(d.someOperation()); // Creator + [Result from Product B]
console.log(createProduct('A').operate()); // Result from Product A
